package co.edu.umb.boleteria;
import co.edu.umb.boleteria.domain.*;import co.edu.umb.boleteria.repository.*;import co.edu.umb.boleteria.service.ReservaService;import co.edu.umb.boleteria.web.dto.ReservaDto;import co.edu.umb.boleteria.web.excepciones.SinDisponibilidadException;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;import java.lang.reflect.Field;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.concurrent.atomic.AtomicReference;import static org.junit.jupiter.api.Assertions.*;
@Testcontainers @SpringBootTest class ReservaConcurrenciaTest {
 @Container static PostgreSQLContainer<?> db=new PostgreSQLContainer<>("postgres:16-alpine");
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.write.jdbc-url",db::getJdbcUrl);r.add("spring.datasource.read.jdbc-url",db::getJdbcUrl);r.add("spring.datasource.write.username",db::getUsername);r.add("spring.datasource.read.username",db::getUsername);r.add("spring.datasource.write.password",db::getPassword);r.add("spring.datasource.read.password",db::getPassword);r.add("POSTGRES_DB",db::getDatabaseName);r.add("POSTGRES_USER",db::getUsername);r.add("POSTGRES_PASSWORD",db::getPassword);r.add("APP_DEVOPS_PASSWORD_HASH",()->"$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy");r.add("spring.jpa.hibernate.ddl-auto",()->"create-drop");}
 @Autowired ReservaService service;@Autowired LocalidadRepository localidades;@Autowired ReservaRepository reservas;
 private LocalidadGeneral aforo(int cupos)throws Exception{var c=LocalidadGeneral.class.getDeclaredConstructor();c.setAccessible(true);var g=c.newInstance();set(g,"nombre","Test aforo");set(g,"precio",new BigDecimal("100"));set(g,"capacidadTotal",cupos);set(g,"cuposDisponibles",cupos);set(g,"estado",EstadoLocalidad.DISPONIBLE);return localidades.saveAndFlush(g);}
 private Asiento asiento()throws Exception{var c=Asiento.class.getDeclaredConstructor();c.setAccessible(true);var a=c.newInstance();set(a,"nombre","Asiento test");set(a,"codigoSilla","T01");set(a,"precio",new BigDecimal("100"));set(a,"estado",EstadoLocalidad.DISPONIBLE);return localidades.saveAndFlush(a);}
 private void set(Object o,String name,Object value)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);f.set(o,value);return;}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
 private long concurrente(Localidad l,int n,int cantidadMax)throws Exception{var pool=Executors.newFixedThreadPool(Math.min(n,64));var start=new CountDownLatch(1);var ok=new AtomicInteger();var done=new CountDownLatch(n);var fallo=new AtomicReference<Throwable>();for(int i=0;i<n;i++){final int q=ThreadLocalRandom.current().nextInt(1,cantidadMax+1);pool.submit(()->{try{start.await();service.crearReserva(l.getId(),UUID.randomUUID().toString(),q);ok.incrementAndGet();}catch(SinDisponibilidadException expected){}catch(Throwable e){fallo.compareAndSet(null,e);}finally{done.countDown();}});}start.countDown();assertTrue(done.await(90,TimeUnit.SECONDS));pool.shutdownNow();if(fallo.get()!=null)fail("Falló una operación concurrente",fallo.get());return ok.get();}
 @Test void pc01UnSoloExitoParaUnAsiento()throws Exception{Asiento l=asiento();assertEquals(1,concurrente(l,200,1));}
 @Test void pc02TrescientosIntentosSobreCienCupos()throws Exception{LocalidadGeneral l=aforo(100);assertEquals(100,concurrente(l,300,1));assertEquals(0,localidades.findById(l.getId()).orElseThrow().getCuposDisponibles());}
 @Test void pc03LaSumaNuncaSobrepasaCien()throws Exception{LocalidadGeneral l=aforo(100);concurrente(l,200,4);long reservadas=reservas.findAll().stream().filter(r->r.getLocalidad().getId().equals(l.getId())&&r.getEstado()==EstadoReserva.ACTIVA).mapToLong(Reserva::getCantidad).sum();assertTrue(reservadas<=100);}
 @Test void confirmarCancelarYExpirarLiberanEnLosEstadosEsperados()throws Exception{LocalidadGeneral l=aforo(3);ReservaDto confirmable=service.crearReserva(l.getId(),"confirmar",1);assertEquals(EstadoReserva.CONFIRMADA,service.confirmar(confirmable.reservaId()).getEstado());assertThrows(SinDisponibilidadException.class,()->service.confirmar(confirmable.reservaId()));ReservaDto cancelable=service.crearReserva(l.getId(),"cancelar",1);service.cancelar(cancelable.reservaId());assertEquals(EstadoReserva.CANCELADA,reservas.findById(cancelable.reservaId()).orElseThrow().getEstado());ReservaDto vencida=service.crearReserva(l.getId(),"expirar",1);Reserva r=reservas.findById(vencida.reservaId()).orElseThrow();Instant t=Instant.now().minusSeconds(30);set(r,"fechaCreacion",t.minusSeconds(60));set(r,"fechaExpiracion",t);reservas.saveAndFlush(r);assertEquals(1,service.expirarVencidas());assertEquals(EstadoReserva.EXPIRADA,reservas.findById(vencida.reservaId()).orElseThrow().getEstado());assertEquals(2,localidades.findById(l.getId()).orElseThrow().getCuposDisponibles());}
}
